  function playerClassPortrait(){return isNecromancer()?'assets/classes/necromancer_portrait.webp':isWarlock()?'assets/classes/warlock_portrait.webp':isElementalist()?'assets/classes/elementalist_portrait.webp':isArcaneMage()?'assets/classes/arcane_mage_portrait.webp':null;}
  function arcaneProgress(){if(!state)return null;state.classProgress=state.classProgress||{};const create=window.ETRANOM_CREATE_ARCANE_PROGRESS||(()=>({charges:0,skillRanks:{},unlockedTalents:[],domainStage:'locked',domainQuest:{started:false,guardianDefeats:0,coreFragments:0,trialComplete:false,complete:false},ascendedSkillId:null,skillCooldowns:{},buffs:{},statuses:{}}));const normalize=window.ETRANOM_NORMALIZE_ARCANE_PROGRESS||((p)=>({...create(),...(p||{})}));state.classProgress.arcaneMage=normalize(state.classProgress.arcaneMage||create());const p=state.classProgress.arcaneMage;if(p.chargeExpiresAt&&Date.now()>=Number(p.chargeExpiresAt)){p.charges=0;p.chargeExpiresAt=null;}if(state.combat)p.chargeExpiresAt=null;for(const skill of (ARCANE()?.skills||[])){if((Number(state.character.level)||1)>=skill.unlockLevel&&!(Number(p.skillRanks[skill.id])>0))p.skillRanks[skill.id]=1;}return p;}
  function arcaneEndCombat(){if(!isArcaneMage())return;const p=arcaneProgress();p.chargeExpiresAt=Number(p.charges)>0?Date.now()+20000:null;}
  function arcaneTalentList(){return (ARCANE()?.talentBranches||[]).flatMap(b=>b.talents.map(t=>({branch:b,talent:t})));}
  function arcaneTalentEffects(){const p=arcaneProgress(),out={};if(!p)return out;for(const {talent} of arcaneTalentList()){if(!p.unlockedTalents.includes(talent[0]))continue;for(const [k,v] of Object.entries(talent[3]||{}))out[k]=(out[k]||0)+Number(v||0);}return out;}
  function arcaneSkillRank(skill){const p=arcaneProgress();return Math.max(0,Math.min(7,Number(p?.skillRanks?.[skill.id])||0));}
  function arcaneSkillAtRank(skill,rank){const out={...skill};for(let i=0;i<Math.max(0,Math.min(6,rank-1));i++)Object.assign(out,skill.upgrades[i]||{});return out;}
  function arcaneDomainStage(){const p=arcaneProgress(),lvl=Number(state?.character?.level)||1;if(p?.domainQuest?.complete)return 'absolute';if(lvl>=50)return 'ascension';if(lvl>=40)return 'mastery';if(lvl>=25)return 'awakening';return 'locked';}
  function arcanePower(){const gear=equipmentBonuses(),tal=arcaneTalentEffects(),c=state.character,combat=state.combat||{};let value=Math.max(1,(characterStat('intellect')+(Number(gear.intellect)||0))*5+(Number(gear.magicPower)||0));let pct=(Number(tal.magicPowerPct)||0)+(Number(combat.arcaneBuffs?.magicPowerPct)||0);if(Number(combat.arcaneDomainTurns)>0){const stage=(ARCANE()?.domain?.stages||[]).find(x=>x.id===arcaneDomainStage());pct+=Number(stage?.magicPowerPct)||0;}return Math.max(1,Math.floor(value*(1+pct/100)));}
  function arcaneMaxCharges(){return 5+(Number(arcaneTalentEffects().maxArcaneChargesBonus)||0);}
  function arcaneUpgradeSkill(id){if(!isArcaneMage())return;const data=ARCANE(),skill=data.skills.find(x=>x.id===id),p=arcaneProgress(),rank=skill?arcaneSkillRank(skill):0;if(!skill||rank<1||rank>=7||state.skillPoints<1)return;state.skillPoints--;p.skillRanks[id]=rank+1;notice='مهارت «'+skill.name+'» به رتبه '+(rank+1)+' ارتقا یافت.';journal(notice);save();render();}
  function arcaneUnlockTalent(id){if(!isArcaneMage())return;const p=arcaneProgress(),entry=arcaneTalentList().find(x=>x.talent[0]===id),t=entry?.talent;if(!t||p.unlockedTalents.includes(id)||state.skillPoints<1)return;const prereq=t[4];if(prereq&&!p.unlockedTalents.includes(prereq)){notice='برای بازکردن این استعداد، ابتدا پیش‌نیاز آن را فعال کن.';render();return;}state.skillPoints--;p.unlockedTalents.push(id);notice='استعداد «'+t[1]+'» فعال شد.';journal(notice);save();render();}
  function arcaneSelectAscended(id){if(!isArcaneMage()||(Number(state.character.level)||1)<25)return;const p=arcaneProgress();if(p.ascendedSkillId){notice='مهارت تعالی‌یافته قبلاً انتخاب شده و تغییر آن به مهر بازآرایی بسیار کمیاب نیاز دارد.';render();return;}const pick=ARCANE().ascendedSkills.find(x=>x.id===id);if(!pick)return;p.ascendedSkillId=id;notice='مهارت تعالی‌یافته «'+pick.name+'» انتخاب شد. این انتخاب دائمی است.';journal(notice);save();render();}
