      const skills='<section class="panel arcane-subpanel"><div class="sect"><b>۱۰ مهارت فعال '+esc(d.specialization)+'</b><small>رتبه ۱ اولیه + ۶ ارتقا • '+sp+' امتیاز مهارت</small></div><p class="muted">ساختار نمایش و مدیریت مهارت‌ها با آرکین‌میج یکسان است؛ نام، اثر، هزینه و ارتقاها مختص این تخصص باقی می‌مانند.</p>'+(d.skills||[]).map(sk=>{const rank=Math.max(1,Number(p.skillRanks?.[sk.id])||1),unlocked=lvl>=Number(sk.unlockLevel||1),next=sk.upgrades?.[rank-1],cost=Number(next?.pointsRequired||next?.points||1);return '<article class="arcane-skill-card '+(unlocked?'':'locked')+'"><div class="arcane-skill-head"><span class="arcane-skill-icon">✧</span><div><b>'+esc(sk.name)+'</b><small>'+esc(sk.en||'')+' • بازشدن سطح '+Number(sk.unlockLevel||1)+'</small></div><strong>'+(unlocked?'رتبه '+rank+'/۷':'قفل')+'</strong></div><p>'+esc(sk.description||'')+'</p><div class="arcane-meta"><span>مانا: '+Number(sk.manaCostPercent??sk.manaPct??sk.manaCost??0)+'٪</span><span>خنک‌شدن: '+Number(sk.cooldownTurns||0)+' نوبت</span><span>هدف: '+esc(sk.target||'طبق شرح مهارت')+'</span></div><details class="arcane-upgrade-list"><summary>مشاهده ارتقاهای مهارت</summary>'+(sk.upgrades||[]).map((u,i)=>'<div><b>رتبه '+(i+2)+'</b><span>'+esc(u.description||u.effect||u.bonus||'ارتقای تخصصی')+'</span></div>').join('')+'</details>'+(unlocked&&rank<7?'<button type="button" data-wizard-rank-up="'+sk.id+'" data-points-required="'+cost+'" '+(sp<cost?'disabled':'')+'>ارتقا به رتبه '+(rank+1)+' • '+cost+' امتیاز</button>':unlocked?'<small>این مهارت به حداکثر رتبه رسیده است.</small>':'<small>در سطح '+Number(sk.unlockLevel||1)+' باز می‌شود.</small>')+'</article>';}).join('')+'</section>';
      const talentIndex=new Map((d.talents||[]).map(t=>[t.id,t]));
