  function useInventoryItem(itemId){const item=state.inventory.find(x=>x.id===itemId&&x.qty>0),spec=CONSUMABLE_ITEMS[itemId];if(!item)return {ok:false,message:"این وسیله در کیف موجود نیست."};let message='';if(spec){const c=state.character,e=spec.effects,maxHp=warriorMaxHp(),healed=Math.min(e.hp||0,maxHp-c.hp),stamina=Math.min(e.stamina||0,warriorMaxStamina()-c.stamina);if(healed<=0&&stamina<=0)return {ok:false,message:"نیازی به مصرف این خوراکی نداری."};c.hp+=healed;c.stamina+=stamina;message=spec.useText;}else if(item.consumable&&item.effect){const c=state.character,power=Math.max(1,Number(item.power)||1);if(item.effect==='hp'){const n=Math.min(power,warriorMaxHp()-c.hp);if(n<=0)return {ok:false,message:'سلامتی تو کامل است.'};c.hp+=n;message='سلامتی '+n+' واحد بازیابی شد.';}else if(item.effect==='mp'){const n=Math.min(power,warriorMaxMp()-c.mp);if(n<=0)return {ok:false,message:'مانای تو کامل است.'};c.mp+=n;message='مانا '+n+' واحد بازیابی شد.';}else if(item.effect==='stamina'){const n=Math.min(power,warriorMaxStamina()-c.stamina);if(n<=0)return {ok:false,message:'استقامت تو کامل است.'};c.stamina+=n;message='استقامت '+n+' واحد بازیابی شد.';}else if(item.effect==='regen'){const n=Math.min(power*3,warriorMaxHp()-c.hp);if(n<=0)return {ok:false,message:'سلامتی تو کامل است.'};c.hp+=n;message='اثر بازسازی فوری '+n+' واحد سلامتی بازگرداند.';}else if(item.effect==='cleanse'){if(!state.combat?.debuffs?.length&&!state.dungeonDebuff)return {ok:false,message:'اثر منفی فعالی برای پاک‌سازی وجود ندارد.'};if(state.combat)state.combat.debuffs=[];state.dungeonDebuff=null;message='اثرات منفی قابل پاک‌سازی برطرف شدند.';}else{message='این معجون فقط در نبرد اثر تقویتی دارد؛ آن را هنگام نبرد مصرف کن.';return {ok:false,message};}}else return {ok:false,message:"این وسیله قابل‌مصرف نیست."};item.qty--;if(item.qty<=0)state.inventory=state.inventory.filter(x=>x!==item);journal("مصرف "+(item.name||itemId)+": "+message);return {ok:true,message};}
