  function ensurePotionProgress(){state.knownPotionRecipes=Array.isArray(state.knownPotionRecipes)?state.knownPotionRecipes:[];state.usedPotionRecipes=Array.isArray(state.usedPotionRecipes)?state.usedPotionRecipes:[];for(const id of state.knownPotionRecipes){const r=POTION_RECIPES.find(x=>x.id===id);if(r&&!state.usedPotionRecipes.includes(id)&&!state.inventory.some(x=>x.id===id&&Number(x.qty)>0))state.inventory.push({id:r.id,name:r.blueprintName,category:'recipe',itemType:'potion_recipe',recipeType:'potion',qty:1,tradeable:true,description:r.description});}}
  function potionRecipePanel(){ensurePotionProgress();const known=POTION_RECIPES.filter(r=>state.knownPotionRecipes.includes(r.id)&&!state.usedPotionRecipes.includes(r.id));return '<div class="npc-profile potion-crafting-panel"><b>⚗️ دفتر معجون‌سازی لیورا</b><p>۴۲ دستور در هفت خانواده و شش کیفیت وجود دارد. هر دستور یک‌بار مصرف است و دقیقاً ۵ معجون می‌سازد. دستور و مواد فقط هنگام ساخت مصرف می‌شوند.</p><small>کیفیت‌ها: معمولی، غیرمعمول، کمیاب، حماسی، افسانه‌ای و اسطوره‌ای.</small>'+(known.length?known.map(r=>'<article class="resident-card"><b>📜 '+esc(r.blueprintName)+'</b><span>'+esc(r.description)+' • قدرت '+r.power+'</span><p>مواد: '+r.materials.map(m=>esc(m.name)+' ×'+m.qty).join('، ')+' • هزینه '+r.gold+' سکه</p><small>موجودی مواد: '+r.materials.map(m=>{const n=state.inventory.find(x=>x.id===m.id)?.qty||0;return esc(m.name)+' '+n+'/'+m.qty;}).join(' • ')+'</small><button type="button" data-interact-action="brew-potion" data-potion-recipe="'+r.id+'" '+(r.materials.every(m=>(state.inventory.find(x=>x.id===m.id)?.qty||0)>=m.qty)&&state.gold>=r.gold?'':'disabled')+'>تحویل دستور و ساخت ۵ معجون</button></article>').join(''):'<p class="muted">هنوز دستور معجون‌سازی کشف نکرده‌ای. دستورها از دشمنان همان محدوده و متناسب با مواد همان دستور به دست می‌آیند.</p>')+'<small>دستورهای مصرف‌شده دوباره قابل استفاده نیستند؛ برای ساخت دوباره باید نسخه تازه‌ای از همان دستور پیدا کنی.</small></div>';}
  function discoverPotionRecipe(def){
    ensurePotionProgress();
    if(!def||def.towerOnly)return null;
    const isBoss=['boss','area_boss'].includes(def.kind);
    const dropped=new Set(def.materialIds||[def.materialId].filter(Boolean));
    const candidates=POTION_RECIPES.filter(r=>r.regionId===def.regionId&&r.materials[0]?.id&&dropped.has(r.materials[0].id)&&!state.knownPotionRecipes.includes(r.id)&&!state.usedPotionRecipes.includes(r.id));
    if(!candidates.length)return null;
    const zoneIndex=ETRANOM_REGION_CONTENT.findIndex(z=>z.id===def.regionId);
    const rarityBands=[['normal','uncommon'],['normal','uncommon','rare'],['uncommon','rare','epic'],['rare','epic','legendary'],['epic','legendary'],['legendary','mythic']];
    const allowed=new Set(rarityBands[zoneIndex]||rarityBands[0]);
    const eligible=candidates.filter(r=>isBoss?(def.regionId==='rootbound_ruins'&&r.qualityId==='mythic'):r.qualityId!=='mythic'&&allowed.has(r.qualityId));
    if(!eligible.length)return null;
    const pick=eligible[Math.floor(Math.random()*eligible.length)];
    const chance=isBoss?2:(Number(pick.dropChance)||0);
    if(Math.random()*100>=chance)return null;
    state.knownPotionRecipes.push(pick.id);
    addInventoryItem({id:pick.id,name:pick.blueprintName,category:'recipe',itemType:'potion_recipe',recipeType:'potion',tradeable:true,description:pick.description},1);
    return pick.blueprintName;
  }
  function brewPotionRecipe(id){ensurePotionProgress();const r=POTION_RECIPES.find(x=>x.id===id);if(!r||!state.knownPotionRecipes.includes(id)||state.usedPotionRecipes.includes(id))return {ok:false,message:'این دستور در اختیار تو نیست یا قبلاً مصرف شده است.'};for(const m of r.materials){const have=state.inventory.find(x=>x.id===m.id)?.qty||0;if(have<m.qty)return {ok:false,message:'مواد کافی نیست: '+m.name+' '+have+'/'+m.qty+'. هیچ چیزی مصرف نشد.'};}if(state.gold<r.gold)return {ok:false,message:'برای ساخت این معجون '+r.gold+' سکه لازم داری.'};r.materials.forEach(m=>{const it=state.inventory.find(x=>x.id===m.id);it.qty-=m.qty;});state.inventory=state.inventory.filter(x=>(x.qty||0)>0);state.gold-=r.gold;addInventoryItem({id:r.potionId,name:r.potionName,category:'consumable',description:r.description,effect:r.effect,power:r.power,quality:r.quality,consumable:true},5);state.knownPotionRecipes=state.knownPotionRecipes.filter(x=>x!==id);state.inventory=state.inventory.filter(x=>x.id!==id);state.usedPotionRecipes.push(id);journal('ساخت ۵ عدد '+r.potionName+'؛ دستور یک‌بارمصرف برای همیشه مصرف شد.');return {ok:true,message:'۵ عدد «'+r.potionName+'» ساخته شد. دستور، مواد و '+r.gold+' سکه مصرف شدند؛ این دستور دیگر قابل استفاده نیست.'};}
  function grantClassStarterKit(){if(state.classStarterGiftClaimed)return [];const className=state.character.archetype||"جنگجو",catalog=equipmentCatalogFor(className),chosen=["mainWeapon","armor","boots"].map(slot=>catalog.find(x=>x.slot===slot&&x.id.endsWith("_0"))).filter(Boolean);state.equipmentSlots=state.equipmentSlots||{};chosen.forEach(item=>{const gift={...item,requiredPlayerLevel:1,durability:100,maxDurability:100,upgradeLevel:0,effects:{...(item.effects||{})}};state.equipmentSlots[item.slot]=gift;});state.classStarterGiftClaimed=true;const labels=chosen.map(x=>x.name);journal("هدیه آغازین کلاس "+className+" دریافت شد: "+labels.join("، ")+"؛ هر سه آیتم سطح ۱ و کیفیت معمولی دارند.");msg("به‌عنوان هدیه ورود، سه تجهیز ویژه کلاس "+className+" دریافت کردی: "+labels.join("، ")+". این تجهیزات از همین حالا قابل استفاده‌اند.","هدیه آغازین");return chosen;}
  function equipInventoryItem(itemId){const item=state.inventory.find(x=>x.id===itemId&&x.qty>0&&(x.slot||x.category==="equipment"||String(x.id||"").startsWith("crafted_")));if(!item)return {ok:false,message:"این تجهیز در کیف موجود نیست."};if(!EQUIPMENT_SLOTS.some(s=>s[0]===item.slot)){const slotIndex=ETRANOM_SLOTS.indexOf(item.slot);if(slotIndex>=0)item.slot=EQUIPMENT_SLOTS[slotIndex]?.[0]||null;}if(!item.slot||!EQUIPMENT_SLOTS.some(s=>s[0]===item.slot))return {ok:false,message:"جایگاه تجهیز معتبر نیست؛ این آیتم قابل پوشیدن نیست."};const requiredLevel=(Number(item.itemLevel||item.level)||1)<=1?1:(Number(item.requiredPlayerLevel)||5);if((state.character.level||1)<requiredLevel)return {ok:false,message:"سطح بازیکن برای پوشیدن این آیتم کافی نیست؛ سطح موردنیاز: "+requiredLevel+"."};state.equipmentSlots=state.equipmentSlots||{};const slot=item.slot,oldBonus=equipmentBonuses();if(state.equipmentSlots[slot])addInventoryItem({...state.equipmentSlots[slot],requiredPlayerLevel:1},1);item.qty--;if(item.qty<=0)state.inventory=state.inventory.filter(x=>x!==item);const equipped={...item,itemLevel:Number(item.itemLevel||item.level)||1,effects:{...(item.effects||item.stats||{})},durability:100,maxDurability:100,upgradeLevel:0};delete equipped.qty;state.equipmentSlots[slot]=ensureGearState(equipped);const nextBonus=equipmentBonuses();state.character.mp=clamp((state.character.mp||0)+(gearManaValue(nextBonus)-gearManaValue(oldBonus)),0,warriorMaxMp());state.character.stamina=clamp(state.character.stamina||0,0,warriorMaxStamina());journal("تجهیز "+equipped.name+" در جایگاه "+(EQUIPMENT_SLOTS.find(x=>x[0]===slot)?.[1]||slot)+"؛ آیتم قبلی به کیف بازگشت.");return {ok:true,message:equipped.name+" با موفقیت مجهز شد."};}
  // v124: normalize legacy and split inventory stores before rendering. Older saves
  // used quantity/count/amount and some content packs stored materials separately.
  function normalizeInventoryRecord(raw,index=0,allowImplicitQuantity=false){
    if(typeof raw==='string'&&raw.trim())return {id:raw.trim(),name:raw.trim(),qty:1};
    if(!raw||typeof raw!=='object'||Array.isArray(raw))return null;
    const id=String(raw.id??raw.itemId??raw.materialId??raw.key??raw.slug??'').trim();
    const name=String(raw.name??raw.name_fa??raw.label??raw.title??id).trim();
    if(!id&&!name)return null;
    const rawQty=raw.qty??raw.quantity??raw.count??raw.amount??raw.stackSize??raw.stack;
    if(rawQty==null&&!allowImplicitQuantity)return null;
    const qty=rawQty==null?1:Number(rawQty);
    if(!Number.isFinite(qty)||qty<=0)return null;
    return {...raw,id:id||('legacy_item_'+index),name:name||id||('آیتم قدیمی '+(index+1)),qty};
  }
  function inventoryStoreRecords(store,allowImplicitQuantity=false){
    if(Array.isArray(store))return store.map((x,i)=>normalizeInventoryRecord(x,i,allowImplicitQuantity)).filter(Boolean);
    if(store&&typeof store==='object')return Object.entries(store).map(([key,value],i)=>{
      if(typeof value==='number'||typeof value==='string')return normalizeInventoryRecord({id:key,name:key,qty:value},i,false);
      return normalizeInventoryRecord({...value,id:value?.id??key},i,allowImplicitQuantity);
    }).filter(Boolean);
    return [];
  }
  function normalizeInventoryState(){
    const primary=inventoryStoreRecords(state.inventory,true);
    const merged=[...primary],byId=new Map(primary.map((item,index)=>[item.id,index]));
    // Import legacy split stores once only. The marker prevents consumed items
    // from being re-imported from an old mirror on every repaint.
    if(!state._inventoryStoresMigratedV124){
      ['materialInventory','materials','itemInventory','items','resources','backpack'].forEach(key=>{
        inventoryStoreRecords(state[key],false).forEach(item=>{
          const existingIndex=byId.get(item.id);
          if(existingIndex==null){byId.set(item.id,merged.length);merged.push(item);}
          else if(!merged[existingIndex].slot&&!item.slot){
            // max avoids double-counting when a legacy field mirrors the main bag.
            merged[existingIndex].qty=Math.max(Number(merged[existingIndex].qty)||0,Number(item.qty)||0);
            ['category','type','description','quality','effect','power','consumable'].forEach(k=>{if(merged[existingIndex][k]==null&&item[k]!=null)merged[existingIndex][k]=item[k];});
          }
        });
      });
      state._inventoryStoresMigratedV124=true;
    }
    state.inventory=merged;
    return merged;
  }
  function inventoryItemKind(item){
    const category=String(item?.category||item?.type||item?.kind||'').toLowerCase();
    const id=String(item?.id||'');
    const isGear=!!(item?.slot||/equipment|gear|weapon|armor/.test(category)||id.startsWith('crafted_')&&!!item?.effects);
    if(isGear)return 'equipment';
    const knownMaterials=new Set();
    (FIRST_REGION_ENCOUNTERS||[]).forEach(enemy=>{(Array.isArray(enemy.materialIds)?enemy.materialIds:[enemy.materialId].filter(Boolean)).forEach(x=>knownMaterials.add(String(x)));});
    (ETRANOM_REGION_CONTENT||[]).forEach(region=>(region.mats||[]).forEach(x=>knownMaterials.add(String(x))));
    (window.ETRANOM_RUNTIME_CONTENT?.materials||[]).forEach(x=>knownMaterials.add(String(x.id||'')));
    if(/material|resource|gather|ore|herb|wood|stone|مواد|منبع/.test(category)||knownMaterials.has(id))return 'materials';
    if(/recipe|blueprint|schematic|دستور|نقشه/.test(category+' '+id)||id.includes('_recipe_'))return 'recipes';
    if(/quest|mission|key|relic|مأموریت|کلید|یادگار/.test(category))return 'quest';
    if(item?.consumable||item?.effect||CONSUMABLE_ITEMS[id]||/consumable|potion|food|معجون|خوراک/.test(category))return 'consumables';
    return 'other';
  }
  function equipmentManagementView(){
    const inventoryEntries=normalizeInventoryState();
    state.equipmentSlots=state.equipmentSlots||{};
    const equipped=EQUIPMENT_SLOTS.map(([slot,label])=>{
      const it=ensureGearState(state.equipmentSlots[slot]);
      const pct=it?Math.max(0,Math.min(100,Math.round(it.durability/Math.max(1,it.maxDurability)*100))):0;
      return '<article class="gear-slot-card '+(it?'occupied':'empty')+'"><div class="gear-slot-top"><span>'+label+'</span><b>'+(it?'+'+(it.upgradeLevel||0):'خالی')+'</b></div>'+(it?'<strong>'+esc(it.name)+'</strong><small>سطح آیتم '+(it.itemLevel||1)+' • '+esc(it.rarity||'معمولی')+'</small><div class="gear-durability"><i style="width:'+pct+'%"></i></div><small>دوام '+it.durability+'/'+it.maxDurability+' • '+pct+'٪</small><p>'+esc(effectSummary(it.effects||it.stats||{}))+'</p><button type="button" data-unequip-slot="'+slot+'">انتقال به کیف</button>':'<strong>بدون تجهیز</strong><small>از کیف یک آیتم مناسب این جایگاه انتخاب کن.</small>')+'</article>';
    }).join('');
    const entries=inventoryEntries.filter(x=>x&&Number(x.qty)>0);
    const groups={equipment:[],materials:[],consumables:[],recipes:[],quest:[],other:[]};
    entries.forEach(item=>groups[inventoryItemKind(item)].push(item));
    const totalQty=entries.reduce((sum,x)=>sum+Math.max(0,Number(x.qty)||0),0);
    const section=(key,title,icon,renderItem)=>{
      const list=groups[key];
      return '<section class="inventory-category inventory-category-'+key+'"><div class="sect"><b>'+icon+' '+title+'</b><small>'+list.length+' نوع • '+list.reduce((n,x)=>n+Number(x.qty||0),0)+' عدد</small></div>'+(list.length?list.map(renderItem).join(''):'<p class="muted inventory-empty">در حال حاضر موردی در این دسته نداری.</p>')+'</section>';
    };
    const gearCards=it=>'<article class="gear-bag-card inventory-item-card"><div><b>'+esc(it.name||it.id)+'</b><small>'+esc(EQUIPMENT_SLOTS.find(x=>x[0]===it.slot)?.[1]||it.slot||'تجهیز')+' • سطح '+(it.itemLevel||it.level||1)+' • '+esc(it.rarity||'معمولی')+' • تعداد '+it.qty+'</small><small>'+esc(effectSummary(it.effects||it.stats||{}))+'</small></div><button type="button" data-equip-item="'+esc(it.id)+'">تجهیز</button></article>';
    const simpleCards=(it,key)=>'<article class="gear-bag-card inventory-item-card" data-inventory-item="'+esc(it.id)+'"><div><b>'+esc(it.name||it.id)+'</b><small>شناسه: '+esc(it.id)+' • تعداد: '+Number(it.qty||0)+(it.quality?' • کیفیت: '+esc(it.quality):'')+'</small>'+(it.description?'<small>'+esc(it.description)+'</small>':'')+'</div>'+(key==='consumables'&&(it.consumable||it.effect||CONSUMABLE_ITEMS[it.id])?'<button type="button" data-use-item="'+esc(it.id)+'">استفاده</button>':'')+'</article>';
    return '<section class="panel equipment-management inventory-full-view"><div class="sect"><b>تجهیزات شخصیت</b><small>'+Object.values(state.equipmentSlots).filter(Boolean).length+' / '+EQUIPMENT_SLOTS.length+' جایگاه پر</small></div><div class="gear-slots-grid">'+equipped+'</div><div class="inventory-summary"><b>موجودی کامل کیف</b><span>'+entries.length+' نوع آیتم • '+totalQty+' عدد در مجموع</span></div>'+
      section('equipment','تجهیزات موجود در کیف','⚔️',gearCards)+
      section('materials','مواد و منابع','⛏️',it=>simpleCards(it,'materials'))+
      section('consumables','معجون‌ها و اقلام مصرفی','⚗️',it=>simpleCards(it,'consumables'))+
      section('recipes','دستورها و نقشه‌ها','📜',it=>simpleCards(it,'recipes'))+
      section('quest','اقلام مأموریتی و کلیدها','✦',it=>simpleCards(it,'quest'))+
      section('other','سایر آیتم‌ها','🎒',it=>simpleCards(it,'other'))+
      '<div class="gear-note">نمایش کوله از موجودی اصلی و ذخیره‌های قدیمی مواد/اقلام یکپارچه شده است. '+entries.length+' رکورد دارای موجودی مثبت در فهرست قرار دارد؛ هیچ آیتم ناشناخته‌ای حذف یا پنهان نمی‌شود. تعویض جایگاه، تجهیز قبلی را به کیف بازمی‌گرداند و ویژگی‌های تجهیزات مجهز در محاسبات شخصیت و نبرد اعمال می‌شوند.</div></section>';
  }
