  function routeDamageToSummonedLegion(combatRef, damage, sourceName){
    let remaining=Math.max(0,Math.floor(Number(damage)||0));
    if(!remaining||!combatRef||!isNecromancer())return remaining;
    const ids=new Set((combatRef.summonedLegionIds||[]).map(String));
    if(!ids.size)return remaining;
    const p=wizardRuntimeProgress();
    const guard=(p.legion||[]).find(m=>ids.has(String(m.id||m.speciesId||m.name))&&Number(m.hp)>0);
    if(!guard)return remaining;
    const before=Math.max(0,Number(guard.hp)||0),absorbed=Math.min(before,remaining);
    guard.hp=Math.max(0,before-absorbed);remaining-=absorbed;
    msg('«'+(sourceName||'دشمن')+'» به جای قهرمان به هیولای احضاری «'+(guard.name||'نگهبان لژیون')+'» حمله کرد؛ '+absorbed+' آسیب جذب شد. سلامت همراه: '+guard.hp+'/'+(guard.maxHp||before)+'.');
    if(guard.hp<=0){
      combatRef.summonedLegionIds=(combatRef.summonedLegionIds||[]).filter(id=>String(id)!==String(guard.id||guard.speciesId||guard.name));
      msg('هیولای احضاری «'+(guard.name||'همراه لژیون')+'» کشته شد؛ از این پس دشمنان دوباره قهرمان را هدف می‌گیرند.');
    }
    state.classProgress.wizard_necromancer=p;
    return remaining;
  }
