  // Centralized material reward resolver: one independent 30% roll per eligible,
  // unique material. Keeps enemy reward limits and material-name alignment in one place.
  function rollMaterialDrops(def, randomFn=Math.random){
    if(!def||def.towerOnly)return [];
    const limit=def.kind==="area_boss"||def.kind==="boss"?3:def.kind==="miniboss"?2:1;
    const sourceIds=Array.isArray(def.materialIds)?def.materialIds:[def.materialId].filter(Boolean);
    const uniqueIds=[...new Set(sourceIds.filter(id=>typeof id==="string"&&id.length>0))].slice(0,limit);
    return uniqueIds.filter(()=>randomFn()<0.30).map(id=>{
      const sourceIndex=sourceIds.indexOf(id);
      return {id,name:(def.materialNames||[])[sourceIndex]||def.materialName||id};
    });
  }

