  function arcaneDamageEnemy(enemy,damagePct,opts={}){if(!enemy||enemy.hp<=0)return 0;const tal=arcaneTalentEffects(),power=arcanePower(),base=power*(Number(damagePct)||0)/100,penetration=Math.min(80,(Number(opts.defensePenetrationPct)||0)+(Number(enemy.arcaneDebuffs?.defenseDownPct)||0)+(Number(tal.defensePenetrationPct)||0)),def=Math.max(0,Number(enemy.enemyDefense)||0)*(1-penetration/100),mod=Number(state.dungeonDebuff?.outgoingMultiplier)||1,domainBonus=Number(state.combat?.arcaneNextSpellBonusPct)||0,hitChance=clamp(92+(characterStat('perception')-10)*.25+(Number(tal.accuracyBonus)||0)+(Number(opts.accuracyBonus)||0),70,99);if(opts.allowMiss===true&&Math.random()*100>hitChance){msg('جادوی آرکین به هدف برخورد نکرد؛ ادراک و دقت بیشتر احتمال اصابت را بالا می‌برد.');return 0;}const extraDamage=(Number(tal.skillDamagePct)||0)+(opts.explosion?Number(tal.explosionDamagePct)||0:0);let damage=Math.max(1,Math.floor(base*(100/(100+def*1.25))*mod*(1+extraDamage/100)*(1+domainBonus/100)*((opts.isBoss||['boss','area_boss'].includes(enemy.encounterKind))?1+(Number(tal.bossDamagePct)||0)/100:1)));const critChance=Math.min(65,Math.max(0,(Number(tal.critBonus)||0)+(Number(opts.critBonus)||0)+(Number(tal.accuracyBonus)||0)*.15));if(opts.allowCrit!==false&&Math.random()*100<critChance){damage=Math.floor(damage*1.5);msg('ضربه بحرانی آرکین!');}const beforeHp=enemy.hp;enemy.hp=Math.max(0,enemy.hp-damage);if(beforeHp>0&&enemy.hp<=0&&Number(tal.manaOnKillPct)>0)state.character.mp=clamp(state.character.mp+Math.ceil(warriorMaxMp()*tal.manaOnKillPct/100),0,warriorMaxMp());msg('مهارت آرکین به «'+enemy.enemy+'» '+damage+' آسیب وارد کرد.');return damage;}
