  function activateArcaneDomain(){if(!state.combat||state.combat.phase!=='player'||state.combat.enemyTurnPending||!isArcaneMage())return;const c=state.combat,p=arcaneProgress(),lvl=Number(state.character.level)||1,stage=arcaneCurrentStageData();if(lvl<25||!stage){notice='قلمرو در سطح ۲۵ باز می‌شود.';render();return;}if(c.arcaneDomainUsed){notice='در هر نبرد فقط یک بار می‌توان قلمرو را فعال کرد.';render();return;}const mana=arcaneConsumeMana(20);if(!mana){notice='برای فعال‌سازی قلمرو مانای کافی نداری.';render();return;}c.arcaneDomainUsed=true;c.arcaneDomainTurns=stage.durationPlayerTurns;c.arcaneDomainTick=0;c.arcaneAscendedUsed=false;c.arcaneDomainFinalBurstDone=false;for(const e of (c.enemies||[]).filter(x=>x.hp>0)){const boss=['boss','area_boss'].includes(e.encounterKind);arcaneSetDebuff(e,{attackReductionPct:boss?(stage.bossEnemyAttackReductionPct||5):(stage.enemyAttackReductionPct||10),turns:stage.durationPlayerTurns});}msg('قلمرو «تکینگی بی‌نهایت» گشوده شد؛ میدان نبرد به بُعد آرکین تبدیل شد. مدت: '+stage.durationPlayerTurns+' نوبت بازیکن.');arcaneFinishPlayerAction();}
