    if(c.arcanePendingSingularity){const x=c.arcanePendingSingularity;if(Number(x.damagePct)>0)arcaneDamageTargets(enemies.filter(e=>e.hp>0),x.damagePct,{allowCrit:false,allowMiss:false,skillBonusPct:x.skillBonusPct||0});x.ticks--;if(x.ticks<=0){let final=x.finalDamagePct||800;final*=1+(Math.min(6,x.chargesSpent||0)*(x.chargeBonusPct||0)/100);arcaneDamageTargets(enemies.filter(e=>e.hp>0),final,{allowCrit:false,allowMiss:false,skillBonusPct:x.skillBonusPct||0});if(x.secondaryWavePct)arcaneDamageTargets(enemies.filter(e=>e.hp>0),x.secondaryWavePct,{allowCrit:false});c.arcanePendingSingularity=null;}}
    if(Number(c.arcaneDomainTurns)>0){c.arcaneDomainTick=(Number(c.arcaneDomainTick)||0)+1;const stage=arcaneCurrentStageData();if(stage?.id==='mastery'&&c.arcaneDomainTick%2===0){for(const e of enemies.filter(e=>e.hp>0)){const boss=['boss','area_boss'].includes(e.encounterKind);arcaneSetDebuff(e,{attackReductionPct:boss?(stage.bossEnemyAttackReductionPct||7):(stage.enemyAttackReductionPct||15),turns:1});}msg('موج جاذبه قلمرو دشمنان را تضعیف کرد.');}if(stage?.id==='ascension'){arcaneDamageTargets(enemies.filter(e=>e.hp>0),30,{allowCrit:false});}if(stage?.id==='absolute'&&c.arcaneDomainTick%2===0)arcaneDamageTargets(enemies.filter(e=>e.hp>0),50,{allowCrit:false});c.arcaneDomainTurns--;if(c.arcaneDomainTurns<=0&&stage?.id==='absolute'&&!c.arcaneDomainFinalBurstDone){arcaneDamageTargets(enemies.filter(e=>e.hp>0),200,{allowCrit:false});c.arcaneDomainFinalBurstDone=true;msg('هسته مرکزی قلمرو مطلق با انفجار نهایی فروبست.');}}
