      if(a==='ore-ledger-quest'){const npc=worldInteraction;if(npc?.id)interactionTabMemory.set(npc.id,'quests');if(!npc||npc.kind!=='npc')return;state.oreLedgerQuest=state.oreLedgerQuest||{stage:0,completed:false};const q=state.oreLedgerQuest,take=(id,n)=>consumeInventoryQuantity(id,n);let line='';if(q.completed){line='دفتر محموله‌ها به بایگانی بازگشته است. وِس اکنون هر شب نسخه‌ای پشتیبان می‌نویسد و دیگر هیچ واگنی بی‌ثبت وارد کوره نمی‌شود.';}else if(q.stage===0){if(npc.id!=='guildmaster_toren')line='برای آغاز بررسی دفتر گمشده، با تورِن استاد انجمن صحبت کن.';else{q.stage=1;questPopup={type:'accepted',title:'دفتر گمشده معدن',text:'مأموریت آغاز شد: از برام درباره آخرین مُهر شیفت معدن پرس‌وجو کن.'};line='تورِن دفتر چرمی را باز می‌کند: «یک برگ از ثبت محموله‌های معدن ناپدید شده. برام آهنگر مُهرهای قدیمی را می‌شناسد؛ از او بپرس آخرین بار دفتر کجا بوده.»';journal('روایت فرعی «دفتر گمشده معدن» را از تورِن پذیرفتی؛ مرحله اول: پرس‌وجو از برام.');}}else if(q.stage===1){if(npc.id!=='smith_bram')line='برام، آهنگر شهر، آخرین مُهر شیفت معدن را به خاطر دارد.';else{q.stage=2;line='برام مُهر آهنی را زیر نور می‌گیرد: «این مُهر پیش از بسته‌شدن تونل روی واگن شماره هفت بوده. دو نمونه سنگ‌آهن لازم داریم تا وزن ثبت‌شده را با بار واقعی مقایسه کنیم؛ دو سنگ‌آهن بیاور و دوباره پیش من برگرد.»';journal('برام مُهر شیفت را شناسایی کرد؛ مرحله دوم: دو سنگ‌آهن تهیه کن و به برام تحویل بده.');}}else if(q.stage===2){if(npc.id!=='smith_bram')line='برام، آهنگر شهر، برای سنجش وزن واگن شماره هفت دو سنگ‌آهن می‌خواهد.';else if(!take('iron_ore',2))line='برام می‌گوید: «برای مقایسه وزن، دو سنگ‌آهن خام لازم دارم. از معدن سهمیه روزانه بگیر.»';else{q.stage=3;line='برام دو سنگ را روی ترازو می‌گذارد. وزن با دفتر اصلی جور درمی‌آید: «واگن شماره هفت دزدیده نشده؛ بارش دوبار ثبت شده. گزارش را به تورِن برگردان تا پرونده بسته شود.»';journal('دو سنگ‌آهن برای سنجش مصرف شد؛ مشخص شد اختلاف وزن از ثبت تکراری واگن هفت بوده است. مرحله پایانی: بازگشت به تورِن.');}}else if(q.stage===3&&npc.id==='guildmaster_toren'){q.stage=4;q.completed=true;const paidGold=questGoldReward(26,state.character.level);questPopup={type:'completed',title:'دفتر گمشده معدن',text:'اختلاف دفتر معدن حل شد. پاداش '+formatGameNumber(paidGold)+' سکه و ۲۰ تجربه دریافت کردی.'};state.gold+=paidGold;grantPersonalQuestXp(20);state.npcRelations.guildmaster_toren=Math.min(10,(state.npcRelations.guildmaster_toren||0)+2);state.npcRelations.smith_bram=Math.min(10,(state.npcRelations.smith_bram||0)+1);line='تورِن گزارش را مهر می‌کند: «پس نه دزدی در کار بوده و نه کم‌فروشی؛ فقط یک خطای ثبت. از اینکه پیش از متهم‌کردن کارگران حقیقت را پیدا کردی ممنونم.» '+formatGameNumber(paidGold)+' سکه و ۲۰ تجربه دریافت کردی.';journal('روایت فرعی «دفتر گمشده معدن» کامل شد؛ اختلاف محموله واگن هفت خطای ثبت بود. پاداش: '+formatGameNumber(paidGold)+' سکه و ۲۰ تجربه.');}else line='تورِن منتظر گزارش نهایی توست؛ نتیجه سنجش را به او بازگردان.';if(line){msg(line,npc.name);state.npcMemory[npc.id]=state.npcMemory[npc.id]||[];state.npcMemory[npc.id].push({kind:'side_quest',at:Date.now(),reply:line,quest:'ore-ledger'});state.npcMemory[npc.id]=state.npcMemory[npc.id].slice(-30);notice=q.completed?'روایت فرعی دفتر گمشده معدن کامل شد.':'پیشرفت روایت فرعی ثبت شد.';}save();render();return;}
