      if(a==='personal-quest'){const npc=worldInteraction;if(!npc||npc.kind!=='npc')return;state.personalQuests=state.personalQuests||{};const book=state.personalQuests[npc.id]||(state.personalQuests[npc.id]={completed:0,active:null,history:[]});book.completed=Math.max(0,Math.min(10,Math.floor(Number(book.completed)||0)));book.history=Array.isArray(book.history)?book.history:[];const idx=book.completed,level=Number(state.character.level)||1;interactionTabMemory.set(npc.id,'quests');if(book.active){const q=book.active,have=(state.inventory||[]).filter(x=>x.id===q.itemId).reduce((sum,x)=>sum+Math.max(0,Number(x.qty)||0),0);if(have<q.qty){notice=npc.name+' می‌گوید: «برای ادامه، '+q.qty+' عدد '+q.itemName+' لازم دارم. '+q.title+' را فراموش نکن.»';msg(notice,npc.name);save();render();return;}let remaining=q.qty;for(const entry of state.inventory||[]){if(entry.id!==q.itemId||remaining<=0)continue;const take=Math.min(remaining,Math.max(0,Number(entry.qty)||0));entry.qty-=take;remaining-=take;}state.inventory=(state.inventory||[]).filter(x=>(Number(x.qty)||0)>0);const paidGold=questGoldReward(q.rewardGold,state.character.level);state.gold+=paidGold;grantPersonalQuestXp(q.rewardXp);state.npcMemory[npc.id]=state.npcMemory[npc.id]||[];state.npcMemory[npc.id].push({kind:'personal_quest_completed',questId:q.id,at:Date.now(),day:state.worldClock?.day||1});state.npcMemory[npc.id]=state.npcMemory[npc.id].slice(-20);book.history.push({id:q.id,day:state.worldClock?.day||1,title:q.title,itemId:q.itemId,qty:q.qty});book.completed=Math.min(10,book.completed+1);questPopup={type:'completed',title:q.title,text:'درخواست '+q.qty+' '+q.itemName+' تحویل شد. مأموریت '+book.completed+' از ۱۰ کامل شد؛ '+formatGameNumber(paidGold)+' سکه و '+q.rewardXp+' تجربه دریافت کردی.'};book.active=null;state.npcRelations[npc.id]=Math.min(10,(state.npcRelations[npc.id]||0)+1);const thanks=['«دقیقاً همان چیزی بود که لازم داشتم. زحمتت را فراموش نمی‌کنم.»','«با این کمک، کار امروزمان راه افتاد. سپاسگزارم.»','«می‌دانستم می‌توانم روی تو حساب کنم؛ پاداش حق توست.»'];const line=thanks[(book.completed-1)%thanks.length]+' مأموریت '+book.completed+' از ۱۰ کامل شد؛ '+q.rewardGold+' سکه و '+q.rewardXp+' تجربه گرفتی.';msg(line,npc.name);journal('مأموریت شخصی '+book.completed+'/۱۰ برای '+npc.name+' کامل شد: '+q.title+'؛ پاداش '+formatGameNumber(paidGold)+' سکه و '+q.rewardXp+' تجربه.');notice=book.completed>=10?'هر ۱۰ مأموریت شخصی '+npc.name+' تکمیل شد.':'مأموریت '+book.completed+' از ۱۰ برای '+npc.name+' کامل شد؛ مأموریت بعدی آماده دریافت است.';}else if(idx>=10){notice=npc.name+' لبخند می‌زند: «هر ده مأموریت شخصی‌مان را انجام داده‌ای؛ فعلاً کار تازه‌ای ندارم.»';msg(notice,npc.name);}else{const q=personalQuestSpec(npc,idx);if(!q){notice='برای این شخصیت مأموریت دیگری تعریف نشده است؛ پیشرفت قبلی حفظ شد.';}else if(level<q.level){notice='مأموریت بعدی '+npc.name+' در سطح '+q.level+' باز می‌شود؛ سطح فعلی تو '+level+' است.';msg(notice,npc.name);}else{book.active=q;questPopup={type:'accepted',title:q.title,text:'مأموریت پذیرفته شد: '+q.qty+' عدد '+q.itemName+' تهیه کن و برای تحویل، دوباره به '+npc.name+' مراجعه کن.'};const line=npc.name+' می‌گوید: «'+q.title+'؛ لطفاً '+q.qty+' عدد '+q.itemName+' برایم بیاور. وقتی آماده شد، دوباره با من صحبت کن.»';msg(line,npc.name);journal('مأموریت شخصی '+(idx+1)+'/۱۰ از '+npc.name+' پذیرفته شد؛ سطح لازم '+q.level+'، درخواست '+q.qty+' '+q.itemName+'.');notice='مأموریت شخصی '+(idx+1)+' از ۱۰ پذیرفته شد؛ درخواست را آماده کن و دوباره به همین NPC برگرد.';}}save();render();return;}
      if(a==='interior-explore'){const o=worldInteraction;if(!o||o.kind==='npc')return;const rooms={market:'قفسه‌های چوبی تا سقف بالا رفته‌اند. بوی ادویه و پارچه تازه در فضاست؛ دفتر حساب بازرگان کنار ترازوی برنجی باز مانده.',inn:'درون مسافرخانه، بخاری سنگی آرام می‌سوزد. اتاق‌های کوچک پیرامون تالار چیده شده‌اند و فانوس شکسته بالای راه‌پله سایه‌ای عجیب می‌اندازد.',smith:'گرمای کوره صورتت را سرخ می‌کند. چکش‌ها، انبرها و قالب‌های آهنی روی دیوار آویخته‌اند و کف کارگاه از براده فلز پوشیده است.',guild:'تالار انجمن بوی کاغذ و چرم می‌دهد. نقشه چهار آبادی روی میز مرکزی باز است و دفتر مأموریت‌ها با مُهر تورِن بسته شده.',alchemy:'شیشه‌های رنگی روی قفسه‌ها برق می‌زنند. هاون سنگی، دفتر فرمول‌ها و بوته‌ای با بخار آبی در گوشه کارگاه دیده می‌شود.',enchanter:'قفسه‌های چوب تیره پر از طومارهای مهرشده‌اند. میز آمون با جوهر آرکین، گچ نشان‌گذاری و سنگ‌های تمرکز پوشیده شده است.',clinic:'تخت‌های مرتب، قفسه دارو و حوضچه شست‌وشو فضای آرامی ساخته‌اند. نارا ابزارهای درمان را با دقت روی پارچه سفید می‌چیند.',stable:'بوی کاه و چرم در اصطبل پیچیده است. زین‌ها آویخته‌اند و اسب خاکستری با شنیدن قدم‌ها گوش‌هایش را تکان می‌دهد.',store:'کیسه‌های غله در ردیف‌های شماره‌گذاری‌شده چیده شده‌اند. دفتر انبار نشان می‌دهد سهم هر آبادی جداگانه ثبت می‌شود.',guard:'نقشه مسیرها به دیوار نصب شده و زره‌ها کنار در آویزان‌اند. از پنجره، نگهبانان رفت‌وآمد جاده را زیر نظر دارند.',mill:'چرخ‌دنده‌های آسیاب با صدای منظم می‌چرخند. روی تیر اصلی، حکاکی بسیار قدیمی چهار خط به‌هم‌پیوسته دیده می‌شود.',farm:'ابزارهای برداشت و صندوق بذر در انبار تعاونی نگهداری می‌شوند. برنامه آبیاری و سهم خانواده‌ها روی تخته‌ای گچی نوشته شده.',baker:'تنور آجری هنوز گرم است. خمیرها زیر پارچه خوابانده شده‌اند و بوی نان تازه همه اتاق را پر کرده است.',well:'پله‌های سنگی تا سکوی چاه پایین می‌روند. آب زلال است و صدای چکیدن قطره‌ها در عمق، پژواکی غیرعادی دارد.',herb:'بسترهای خشک‌کردن گیاهان در نور ملایم قرار دارند. میان برگ‌ها نشانی از گل هفت‌پر دیده می‌شود.',herbalist:'دسته‌های گیاه از تیرهای سقف آویزان‌اند. ایسا نمونه‌ای از رزین شفاف را در ظرف شیشه‌ای نگه داشته که نور را سبز می‌کند.',wood:'اره‌ها و تبرها روی دیوارند و الوارها بر اساس سن خشک‌شدن مرتب شده‌اند. روی یکی از تنه‌ها مُهر قدیمی چهار آبادی مانده است.',hunter:'نقشه ردپاها، تله‌های کوچک و ابزارهای صحرایی در اتاق دیده می‌شوند. شکارچیان فقط جانوران بی‌خطر حاشیه منطقه را ثبت می‌کنند.',carpenter:'بوی چوب تازه و روغن ابزار در کارگاه پیچیده است. قالب‌های اندازه‌گیری کنار میز قرار دارند و تخته‌ها برای ساخت پل آماده‌اند.',mine:'دفتر شیفت معدن کنار چراغ روغنی قرار دارد. نقشه تونل‌های بسته با جوهر سرخ علامت‌گذاری شده است.',smelter:'کوره از پشت شبکه آهنی می‌درخشد. قالب‌های شمش، انبرهای بلند و سطل زغال در جای خود چیده شده‌اند.',stone:'گرد سنگ در نور پنجره شناور است. قطعات نیمه‌تراشیده با نشانه‌های مختلف روی میز قرار دارند.',ore:'کیسه‌های سنگ‌آهن وزن‌کشی و مُهر شده‌اند. در دفتر قدیمی، یک محموله با علامت هلال شکسته ثبت شده است.',miners_inn:'تالار گرم معدن‌کاران با میزهای سنگین و نیمکت‌های چوبی پر شده. چراغ‌های روغنی برای شیفت شب آماده‌اند.'};const clueMap={mill:'چرخ آسیاب',herbalist:'رزین سبز',ore:'دفتر محموله'};interiorView={id:o.id,kind:o.kind,name:o.name,description:rooms[o.kind]||'فضای داخلی ساده اما مرتب است؛ ابزارها و وسایل روزمره هرکدام جای مشخصی دارند.',icon:({market:'🛍️',inn:'🕯️',smith:'⚒️',guild:'📜',alchemy:'⚗️',enchanter:'✧',clinic:'✚',stable:'🐎',store:'🌾',guard:'🛡️',mill:'⚙️',farm:'🌱',baker:'🍞',well:'💧',herb:'🌿',herbalist:'🌿',wood:'🪵',hunter:'🏹',carpenter:'🪚',mine:'⛏️',smelter:'🔥',stone:'🪨',ore:'📦',miners_inn:'🏠'})[o.kind]||'🏡',clue:!!clueMap[o.kind]&&!state.safeClues?.includes(o.kind)};render();return;}
      if(a==='region-quest'||a==='region-quest-truth'||a==='region-quest-seal'){const npc=worldInteraction;if(npc?.id)interactionTabMemory.set(npc.id,'quests');if(!npc||npc.kind!=='npc')return;state.regionQuest=state.regionQuest||{stage:0,completed:false,choice:null};const q=state.regionQuest,take=(id,n)=>consumeInventoryQuantity(id,n);let line='';if(q.completed){line='پیمان چهار آبادی به پایان رسیده است. تورِن نسخه نهایی گزارش را در تالار انجمن نگه می‌دارد؛ مردم هر چهار آبادی از نام تو یاد می‌کنند.';}else if(q.stage===0){if(npc.id!=='guildmaster_toren')line='برای آغاز این ماجرا باید با تورِن، استاد انجمن ماجراجویان، صحبت کنی.';else{q.stage=1;questPopup={type:'accepted',title:'پیمان چهار آبادی',text:'پیمان آغاز شد: دو تخته چوبی برای تعمیر چرخ آسیاب کشتزار به سنا در میدان شهر برسان.'};line='تورِن دفتر چرمی را باز می‌کند: «چهار آبادی با یک پیمان به هم پیوند خورده‌اند. چراغ راه‌های میانشان خاموش شده و هر روستا بخشی از سازوکار را می‌شناسد. اگر می‌خواهی این پیمان را زنده کنی، نخست چرخ آسیاب کشتزار را تعمیر کن. دو تخته چوبی لازم است. با سنا در میدان شهر صحبت کن؛ او تحویل را ثبت می‌کند و برای تعمیر آسیاب می‌فرستد.»';journal('زنجیره مأموریت «پیمان چهار آبادی» را از تورِن پذیرفتی؛ مرحله اول: تعمیر چرخ آسیاب کشتزار.');}}else if(q.stage===1){if(npc.id!=='elder_sena')line='سنا در میدان شهر منتظر دو تخته چوبی سالم برای تعمیر چرخ آسیاب است.';else if(!take('wooden_plank',2))line='سنا می‌گوید: «دو تخته چوبی سالم لازم داریم. آن‌ها را از کارگاه چوب آماده کن و دوباره پیش من بیاور.»';else{q.stage=2;line='سنا دو تخته را برای تعمیر چرخ آسیاب به کشتزار می‌فرستد. «مرحله بعدی، امن‌کردن فانوس راه است؛ میرا در پاسگاه شهر دو رزین درخت می‌خواهد تا پوشش فانوس را تعمیر کند.»';journal('مرحله اول پیمان چهار آبادی انجام شد؛ دو تخته به سنا تحویل شد. مرحله دوم: رساندن دو رزین به میرا.');}}else if(q.stage===2){if(npc.id!=='guard_mira')line='میرا در پاسگاه شهر برای تعمیر فانوس راه دو رزین درخت می‌خواهد.';else if(!take('wood_resin',2))line='میرا می‌گوید: «دو رزین درخت لازم داریم تا پوشش فانوس را تعمیر کنیم. پس از جمع‌آوری، دوباره به پاسگاه برگرد.»';else{q.stage=3;line='میرا رزین را روی درزهای فانوس می‌مالد و نور سبزفام در شیشه می‌دود. «راه روشن شد؛ اما نشان فلزی آن شکسته است. برام آهنگر می‌تواند با یک شمش آهن بست تازه بسازد.»';journal('مرحله دوم پیمان چهار آبادی انجام شد؛ فانوس تعمیر شد. مرحله سوم: رساندن یک شمش آهن به برام.');}}else if(q.stage===3){if(npc.id!=='smith_bram')line='برام آهنگر برای ساخت بست فانوس یک شمش آهن می‌خواهد.';else if(!take('iron_ingot',1))line='برام می‌گوید: «یک شمش آهن برای ساخت بست فلزی لازم است. آن را آماده کن و به آهنگری بیاور.»';else{q.stage=4;line='برام بست فلزی را می‌سازد و مُهر آهنگری را روی آن می‌کوبد. «چهار راه دوباره به هم وصل شدند. اما پیمان قدیمی یک راز دارد؛ آمون در مغازه افسونگری می‌داند آن را آشکار کنیم یا مهر و موم نگه داریم.»';journal('مرحله سوم پیمان چهار آبادی انجام شد؛ بست آهنی ساخته شد. مرحله پایانی: گفت‌وگو با آمون در نیایشگاه.');}}else if(q.stage===4){if(npc.id!=='priest_amon')line='برای پایان پیمان باید نزد آمون، افسونگر شهر، بروی و درباره راز چهار آبادی تصمیم بگیری.';else if(a==='region-quest-seal'||a==='region-quest-truth'){q.completed=true;q.stage=5;questPopup={type:'completed',title:'پیمان چهار آبادی',text:'پیمان چهار آبادی کامل شد. انتخاب نهایی: '+(a==='region-quest-truth'?'آشکارسازی حقیقت':'مهر و موم راز')+'. پاداش و تجربه دریافت شد.'};q.choice=a==='region-quest-truth'?'آشکارسازی حقیقت':'مهر و موم راز';state.gold+=questGoldReward(a==='region-quest-truth'?40:30,state.character.level);grantPersonalQuestXp(a==='region-quest-truth'?35:25);['captain_arden','grain_reeve','woodreeve_fenn','ironreeve_dorn'].forEach(id=>state.npcRelations[id]=Math.min(10,(state.npcRelations[id]||0)+2));line=a==='region-quest-truth'?'آمون مُهر کتیبه را کنار می‌زند. «پس حقیقت را پنهان نمی‌کنیم.» او روایت می‌کند که چهار آبادی بر پایه پیمانی برای محافظت از صدایی در اعماق بنا شده‌اند. ناقوس‌ها نه برای هشدار جنگ، که برای آرام نگه‌داشتن آن صدا ساخته شده‌اند. گزارش را به انجمن می‌بری؛ تورِن پاداش بیشتری می‌پردازد و قول می‌دهد حقیقت را با مردم در میان بگذارد.':'آمون مُهر مومی را روی کتیبه می‌گذارد. «همه حقیقت‌ها را نباید بی‌زمان آشکار کرد.» راز زیرزمین در بایگانی مهروموم‌شده مغازه افسونگری می‌ماند و چهار آبادی به زندگی آرام خود ادامه می‌دهند.';journal('پیمان چهار آبادی را کامل کردی؛ تصمیم نهایی: '+q.choice+'. پاداش و تجربه دریافت شد.');}else line='آمون کتیبه را لمس می‌کند: «اکنون دو راه پیش رو داری؛ حقیقت را آشکار کن یا راز را برای روزی دیگر مهر و موم نگه دار.»';}if(line){msg(line,npc.name);state.npcMemory[npc.id]=state.npcMemory[npc.id]||[];state.npcMemory[npc.id].push({kind:'region_quest',at:Date.now(),reply:line,stage:q.stage});state.npcMemory[npc.id]=state.npcMemory[npc.id].slice(-30);notice=q.completed?'پیمان چهار آبادی کامل شد!':'پیشرفت مأموریت پیمان چهار آبادی ثبت شد.';}save();render();return;}
      if(a==='community-board'){if(worldInteraction?.kind!=='npc'||worldInteraction.id!=='guildmaster_toren'){notice='دفتر رویدادها فقط نزد استاد انجمن نگهداری می‌شود.';render();return;}activeTab='community';worldPanelOpen=true;notice='تورِن دفتر گردهمایی‌های چهار آبادی را باز کرد؛ برای شرکت باید به محل رویداد روز بروی.';render();return;}
