  function organizeInteractionTabs(){
    const win=root.querySelector('.interaction-window');
    if(!win||win.dataset.organized==='1'||win.classList.contains('interior-room'))return;
    const header=win.querySelector(':scope > header');
    if(!header)return;
    const nodes=Array.from(win.children).filter(n=>n!==header&&!n.classList.contains('interaction-tabs')&&!n.classList.contains('interaction-leave'));
    if(!nodes.length)return;
    const groups={result:[],overview:[],services:[],trade:[],quests:[],social:[]};
    const classify=node=>{
      if(node.classList?.contains('service-result-tab'))return 'result';
      const actions=Array.from(node.matches('[data-interact-action]')?[node]:node.querySelectorAll('[data-interact-action]')).map(b=>b.dataset.interactAction||'');
      const textContent=(node.textContent||'').trim();
      const hasTrade=actions.some(a=>a==='sell-surplus'||a==='seller-open'||a.startsWith('buy-')||a==='npc-sell');
      const hasSocial=actions.some(a=>a==='npc-talk'||a==='npc-ask'||a==='npc-gift');
      const hasQuest=actions.some(a=>/quest|request|community|deliver/.test(a));
      const hasService=actions.some(a=>/repair|upgrade|craft|harvest|mill|bake|smelt|well|apiary|hunter|guard|shrine|stable|rent|patrol|alchemy|smith|rest|clinic|gather|info|tool|pickaxe/.test(a));
      if(node.matches('button')){
        if(hasTrade)return 'trade';
        if(hasQuest)return 'quests';
        if(hasSocial)return 'social';
        if(hasService)return 'services';
        return 'overview';
      }
      if(hasTrade)return 'trade';
      if(hasQuest)return 'quests';
      if(hasService)return 'services';
      if(/خرید و فروش|کالاهای قابل فروش|اجناس فروشنده/.test(textContent))return 'trade';
      if(/دفتر مأموریت|مأموریت‌های شخصی|درخواست روزانه|پیمان چهار آبادی|روایت فرعی/.test(textContent))return 'quests';
      if(/تعمیر و ارتقا|خدمات آهنگری|خدمات اقامت|خدمات درمان|دستور ساخت|فرمول پایه/.test(textContent))return 'services';
      return 'overview';
    };
    nodes.forEach(node=>groups[classify(node)].push(node));
    const tabs=[['result','نتیجه عملیات'],['overview','نمای کلی'],['services','خدمات'],['trade','خرید و فروش'],['quests','مأموریت‌ها'],['social','گفت‌وگو']].filter(([key])=>groups[key].length);
    if(!tabs.length)return;
    const nav=document.createElement('nav');
    nav.className='interaction-tabs';
    nav.setAttribute('aria-label','دسته‌بندی تعامل');
    nav.style.cssText='display:flex;gap:7px;overflow-x:auto;overscroll-behavior-x:contain;padding:8px 0;margin:4px 0 12px;position:sticky;top:0;background:#171522;z-index:3;scrollbar-width:thin';
    tabs.forEach(([key,label])=>{
      const button=document.createElement('button');
      button.type='button';button.textContent=label;button.dataset.uiTab=key;button.setAttribute('role','tab');
      button.style.cssText='flex:0 0 auto;min-height:44px;padding:10px 14px;border:1px solid #65533d;border-radius:10px;background:#24212e;color:#f0d9ad;font-weight:700;white-space:nowrap;touch-action:manipulation';
      nav.appendChild(button);
    });
    header.after(nav);
    const panels={};
    tabs.forEach(([key])=>{
      const panel=document.createElement('div');
      panel.dataset.uiPanel=key;panel.setAttribute('role','tabpanel');
      panel.style.cssText='display:flex;flex-direction:column;gap:9px;min-width:0';
      panels[key]=panel;nav.after(panel);
    });
    Object.entries(groups).forEach(([key,list])=>list.forEach(node=>panels[key]?.appendChild(node)));
    const interactionMemoryKey=String(worldInteraction?.id||win.dataset.interactionId||'default');
    const activate=key=>{
      if(!panels[key])return;
      interactionTabMemory.set(interactionMemoryKey,key);
      Object.entries(panels).forEach(([id,panel])=>panel.style.display=id===key?'flex':'none');
      nav.querySelectorAll('[data-ui-tab]').forEach(button=>{
        const selected=button.dataset.uiTab===key;
        button.style.background=selected?'linear-gradient(135deg,#59432b,#302337)':'#24212e';
        button.style.borderColor=selected?'#d4b16e':'#65533d';
        button.setAttribute('aria-selected',selected?'true':'false');
        button.tabIndex=selected?0:-1;
      });
    };
    nav.addEventListener('click',event=>{
      const button=event.target.closest('[data-ui-tab]');
      if(button)activate(button.dataset.uiTab);
    });
    nav.addEventListener('keydown',event=>{
      if(!['ArrowLeft','ArrowRight'].includes(event.key))return;
      const buttons=Array.from(nav.querySelectorAll('[data-ui-tab]'));
      const current=buttons.indexOf(event.target.closest('[data-ui-tab]'));
      if(current<0)return;
      event.preventDefault();
      const next=buttons[(current+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];
      activate(next.dataset.uiTab);next.focus();
    });
    const rememberedTab=interactionTabMemory.get(interactionMemoryKey);
    activate(rememberedTab&&panels[rememberedTab]?rememberedTab:(groups.result.length?'result':tabs[0][0]));
    win.dataset.interactionId=interactionMemoryKey;
    win.dataset.organized='1';
  }
